const SUPABASE_URL = 'https://SEU-PROJETO.supabase.co';
const SERVICE_ROLE = 'COLE_A_SERVICE_ROLE_AQUI';

const entrada = $input.first().json;

return [{
  json: {
    ...entrada,
    supabase_url: String(SUPABASE_URL).replace(/\/$/, ''),
    service_role: SERVICE_ROLE,
  },
}];

function quando(iso) {
  if (!iso) return 'sem horário';
  return new Intl.DateTimeFormat('pt-BR', {
    dateStyle: 'short',
    timeStyle: 'short',
    timeZone: 'America/Sao_Paulo',
  }).format(new Date(iso));
}

function numeroPedido(numero) {
  return '#' + String(numero).padStart(3, '0');
}

function linhasDaConsulta() {
  const linhas = [];
  for (const item of $input.all()) {
    const json = item.json;
    if (Array.isArray(json)) linhas.push(...json);
    else if (json && json.pedido_id) linhas.push(json);
  }
  return linhas;
}

function bloco(item) {
  return [
    numeroPedido(item.numero),
    'Endereço: ' + (item.endereco || '—'),
    'Técnico: ' + (item.tecnico_nome || 'sem técnico'),
    'Horário: ' + quando(item.data_instalacao),
  ].join('\n');
}

const linhas = linhasDaConsulta();
if (linhas.length === 0) return [];

const semEmail = linhas.filter((item) => !String(item.cliente_email || '').trim());
if (semEmail.length > 0) {
  const nomes = semEmail.map((item) => item.cliente_nome || 'cliente sem nome').join(', ');
  throw new Error('Sem e-mail cadastrado para: ' + nomes);
}

const porEmail = new Map();
for (const item of linhas) {
  const email = String(item.cliente_email).trim();
  const grupo = porEmail.get(email) || [];
  grupo.push(item);
  porEmail.set(email, grupo);
}

return [...porEmail.entries()].map(([email, itens]) => {
  const cliente = itens[0].cliente_nome || 'cliente';
  const quantidade = itens.length;
  const palavra = quantidade === 1 ? 'instalação' : 'instalações';
  return {
    json: {
      para: email,
      assunto: 'Amanhã: ' + quantidade + ' ' + palavra,
      corpo: [
        'Olá, ' + cliente + '.',
        '',
        'Sua instalação está marcada para amanhã.',
        '',
        itens.map(bloco).join('\n\n'),
      ].join('\n'),
    },
  };
});

const item = $input.first().json;
const mensagem = (item && item.error && item.error.message) || item.message || JSON.stringify(item);
throw new Error("Automação 2 não enviou o e-mail das instalações de amanhã: " + mensagem);
